<?php $valid ??= false; $token ??= ''; ?><!doctype html>
<html lang="<?= \App\Core\Localization::current() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= \App\Core\t('Email verification') ?> — c0m.me</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><?php require __DIR__ . '/partials/language-switcher.php'; ?><main class="auth-wrap"><a class="brand" href="/">c0m.me</a><section class="auth-card"><span class="eyebrow"><?= \App\Core\t("EMAIL VERIFICATION") ?></span><h1><?= $valid ? \App\Core\t('Confirm your email') : \App\Core\t('Link unavailable') ?></h1><?php if ($valid): ?><p><?= \App\Core\t("Confirm that this email address belongs to you. The link can only be used once.") ?></p><form method="post" action="/verify-email"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="token" value="<?= htmlspecialchars($token, ENT_QUOTES, 'UTF-8') ?>"><button class="button full" type="submit"><?= \App\Core\t("Verify email address") ?></button></form><?php else: ?><p><?= \App\Core\t("This verification link is invalid, expired or already used. Request a new verification email if your account is still pending.") ?></p><a class="button full" href="/login"><?= \App\Core\t("Continue to sign in") ?></a><?php endif; ?></section></main></body></html>
